    function createDefaultReturnConfigWithMainStyle(mainPanel, returnType) {
        const cfg = createDefaultReturnConfig();
        if (mainPanel) {
            cfg.railStyle = mainPanel.railStyle;
            const customKeys = ['postType', 'postSize', 'postW', 'postH', 'postT', 'topRailType', 'topRailSize', 'topRailW', 'topRailH', 'topRailT', 'botRailType', 'botRailSize', 'botRailW', 'botRailH', 'botRailT', 'midRailType', 'midRailSize', 'midRailW', 'midRailH', 'midRailT', 'midRailGap', 'picketType', 'picketSize', 'picketW', 'picketH', 'picketT', 'picketSpacing', 'includeBasePlates', 'basePlateConfig'];
            customKeys.forEach(k => {
                if (mainPanel[k] !== undefined) {
                    if (k === 'basePlateConfig' && mainPanel[k]) {
                        cfg[k] = JSON.parse(JSON.stringify(mainPanel[k]));
                    } else {
                        cfg[k] = mainPanel[k];
                    }
                }
            });
            // Apply return specific post defaults for urban/villa styles
            const style = mainPanel.railStyle || 'classical';
            const isMeshStyle = (style === 'urban_balcony' || style === 'villa_balcony' || style === 'urban_custom' || style === 'villa_custom');
            if (isMeshStyle && returnType === 'leftReturn') {
                cfg.leftPost = 'none';
                cfg.rightPost = 'yes';
            } else {
                cfg.leftPost = 'yes';
                cfg.rightPost = 'none';
            }
        }
        return cfg;
    }

